<?php require __DIR__.'/config.php';$pageTitle='Your cart';$items=[];$total=0;$cart=$_SESSION['cart']??[];if($cart){$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($marks)");$s->execute($ids);$items=$s->fetchAll();}require __DIR__.'/includes/header.php';?>
<h1 class="page-title">Your shopping bag</h1><?php if(!empty($_SESSION['flash'])): ?><div class="notice"><?= h($_SESSION['flash']);unset($_SESSION['flash']); ?></div><?php endif; ?>
<?php if(!$items): ?><div class="empty"><h2>Your cart is taking a little break.</h2><p>Find something you love and add it here.</p><a class="btn" href="<?= url() ?>">Continue shopping</a></div><?php else: ?><div class="cart-layout"><div><?php foreach($items as $p): $qty=(int)($cart[$p['id']]??1);$line=$qty*$p['price'];$total+=$line;?><article class="cart-item"><img src="<?= h($p['image']) ?>" alt=""><div class="grow"><small><?= h($p['category']) ?></small><h3><?= h($p['name']) ?></h3><b><?= money($p['price']) ?></b><p>Quantity: <?= $qty ?></p><form method="post" action="<?= url('cart_action.php') ?>"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><input type="hidden" name="action" value="remove"><button class="link-button">Remove</button></form></div><strong><?= money($line) ?></strong></article><?php endforeach; ?></div><aside class="summary"><h3>Order summary</h3><p><span>Subtotal</span><b><?= money($total) ?></b></p><p><span>Delivery</span><b>Free</b></p><hr><p class="total"><span>Total</span><b><?= money($total) ?></b></p><a class="btn full" href="<?= url('checkout.php') ?>">Continue to checkout</a><a class="back-link" href="<?= url() ?>">Continue shopping</a></aside></div><?php endif; ?><?php require __DIR__.'/includes/footer.php'; ?>
